import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.ChangeDimension{Dimension: 2, Position: mgl32.Vec3{1, 2, 3}, Respawn: true,
#   LoadingScreenID: protocol.Option(uint32(300))}
WITH_LOADING_SCREEN_ID = bytes.fromhex("040000803f000000400000404001012c010000")

# generated by gophertunnel b8bd735:
# &packet.ChangeDimension{Dimension: -1, Position: mgl32.Vec3{-1, 0, 0.5}, Respawn: false}
WITHOUT_LOADING_SCREEN_ID = bytes.fromhex("01000080bf000000000000003f0000")

# generated by gophertunnel b8bd735:
# &packet.ChangeDimension{Dimension: 0, Respawn: false, LoadingScreenID: protocol.Option(uint32(0xdeadbeef))}
HIGH_LOADING_SCREEN_ID = bytes.fromhex("000000000000000000000000000001efbeadde")

GOLDENS = [
    pytest.param(
        v2225.ChangeDimensionPacket(
            dimension_id=2,
            pos=v2225.Vec3(x=1.0, y=2.0, z=3.0),
            respawn=True,
            loading_screen_id=300,
        ),
        WITH_LOADING_SCREEN_ID,
        id="with-loading-screen-id",
    ),
    pytest.param(
        v2225.ChangeDimensionPacket(
            dimension_id=-1,
            pos=v2225.Vec3(x=-1.0, y=0.0, z=0.5),
            respawn=False,
            loading_screen_id=None,
        ),
        WITHOUT_LOADING_SCREEN_ID,
        id="without-loading-screen-id",
    ),
    pytest.param(
        v2225.ChangeDimensionPacket(dimension_id=0, respawn=False, loading_screen_id=0xDEADBEEF),
        HIGH_LOADING_SCREEN_ID,
        id="high-loading-screen-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225], ids=lambda version: version.__name__.rpartition(".")[2])
def test_change_dimension_is_packet_61(version):
    assert version.PACKETS[61] is version.ChangeDimensionPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_change_dimension_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_change_dimension_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
